-- check_all_migrations.sql
-- Paste into Supabase SQL Editor to verify which migrations have been applied.
-- Returns true/false for each migration. false = not yet applied.

SELECT
  (SELECT EXISTS (SELECT 1 FROM information_schema.tables   WHERE table_schema = 'public' AND table_name = 'clients'))                                                                                  AS m001_clients,
  (SELECT EXISTS (SELECT 1 FROM information_schema.tables   WHERE table_schema = 'public' AND table_name = 'role_module_access'))                                                                       AS m002_rbac,
  (SELECT EXISTS (SELECT 1 FROM information_schema.routines WHERE routine_schema = 'public' AND routine_name = 'check_module_access'))                                                                  AS m003_rls,
  (SELECT EXISTS (SELECT 1 FROM information_schema.tables   WHERE table_schema = 'public' AND table_name = 'conflict_questionnaire'))                                                                   AS m004_conflict_q,
  (SELECT EXISTS (SELECT 1 FROM information_schema.columns  WHERE table_schema = 'public' AND table_name = 'clients' AND column_name = 'auth_id'))                                                     AS m005_client_portal,
  (SELECT EXISTS (SELECT 1 FROM information_schema.columns  WHERE table_schema = 'public' AND table_name = 'clients' AND column_name = 'profile_completed_at'))                                        AS m006_self_service,
  (SELECT EXISTS (SELECT 1 FROM information_schema.tables   WHERE table_schema = 'public' AND table_name = 'practice_areas'))                                                                          AS m007_practice_areas,
  (SELECT EXISTS (SELECT 1 FROM information_schema.tables   WHERE table_schema = 'public' AND table_name = 'document_checklists'))                                                                     AS m400_uploads_init,
  (SELECT EXISTS (SELECT 1 FROM pg_extension               WHERE extname = 'pg_cron'))                                                                                                             AS m401_cron_cleanup,
  (SELECT EXISTS (SELECT 1 FROM information_schema.tables   WHERE table_schema = 'public' AND table_name = 'sensitive_field_audit'))                                                                   AS m402_ssn_audit,
  (SELECT EXISTS (SELECT 1 FROM information_schema.columns  WHERE table_schema = 'public' AND table_name = 'documents' AND column_name = 'scan_status'))                                               AS m403_malware,
  (SELECT EXISTS (SELECT 1 FROM information_schema.tables   WHERE table_schema = 'public' AND table_name = 'signature_requests'))                                                                      AS m500_esign_init,
  (SELECT EXISTS (SELECT 1 FROM public.role_module_access rma JOIN public.roles r ON r.id = rma.role_id WHERE rma.module_key = 'esign' AND r.name = 'Owner' AND rma.access_level = 'admin'))          AS m501_esign_access,
  (SELECT EXISTS (SELECT 1 FROM public.role_module_access rma JOIN public.roles r ON r.id = rma.role_id WHERE rma.module_key = 'esign' AND r.name = 'Paralegal' AND rma.access_level = 'write'))      AS m502_paralegal_write,
  (SELECT EXISTS (SELECT 1 FROM information_schema.tables   WHERE table_schema = 'public' AND table_name = 'conflict_checks'))                                                                         AS m600_conflict_checker,
  (SELECT EXISTS (SELECT 1 FROM information_schema.columns  WHERE table_schema = 'public' AND table_name = 'users' AND column_name = 'color'))                                                         AS m700_atty_color,
  (SELECT EXISTS (SELECT 1 FROM information_schema.tables   WHERE table_schema = 'public' AND table_name = 'conversations'))                                                                           AS m800_messaging,
  (SELECT EXISTS (SELECT 1 FROM information_schema.columns  WHERE table_schema = 'public' AND table_name = 'matters' AND column_name = 'reminder_interval_days'))                                      AS m901_doc_discovery,
  (SELECT EXISTS (SELECT 1 FROM information_schema.columns  WHERE table_schema = 'public' AND table_name = 'document_checklists' AND column_name = 'case_types'))                                      AS m902_case_types_col,
  (SELECT EXISTS (SELECT 1 FROM public.role_module_access rma JOIN public.roles r ON r.id = rma.role_id WHERE rma.module_key = 'dashboard' AND r.name = 'Partner Attorney'))                          AS m950_dashboard,
  (SELECT EXISTS (SELECT 1 FROM information_schema.tables   WHERE table_schema = 'public' AND table_name = 'oauth_tokens'))                                                                            AS m1000_calendar_oauth,
  (SELECT EXISTS (SELECT 1 FROM information_schema.columns  WHERE table_schema = 'public' AND table_name = 'key_dates' AND column_name = 'google_event_id'))                                           AS m1001_cal_key_dates,
  (SELECT EXISTS (SELECT 1 FROM pg_constraint              WHERE conname = 'oauth_tokens_provider_check'))                                                                                              AS m1002_outlook_provider,
  (SELECT EXISTS (SELECT 1 FROM information_schema.columns  WHERE table_schema = 'public' AND table_name = 'conversations' AND column_name = 'client_notified_at'))                                    AS m1003_debounce,
  (SELECT EXISTS (SELECT 1 FROM information_schema.tables   WHERE table_schema = 'public' AND table_name = 'enabled_modules'))                                                                         AS m1050_enabled_modules,
  (SELECT EXISTS (SELECT 1 FROM information_schema.tables   WHERE table_schema = 'public' AND table_name = 'email_log'))                                                                               AS m1103_email_log,
  (SELECT EXISTS (SELECT 1 FROM information_schema.columns  WHERE table_schema = 'public' AND table_name = 'users' AND column_name = 'ical_token'))                                                    AS m1104_ical_token,
  (SELECT EXISTS (SELECT 1 FROM public.enabled_practice_areas WHERE practice_area_key = 'family_law'))                                                                                                 AS m1105_pa_backfill,
  (SELECT EXISTS (SELECT 1 FROM information_schema.tables   WHERE table_schema = 'public' AND table_name = 'draft_templates'))                                                                         AS m1106_doc_drafting,
  (SELECT EXISTS (SELECT 1 FROM information_schema.tables   WHERE table_schema = 'public' AND table_name = 'client_personal_injury'))                                                                  AS m1107_more_pa,
  (SELECT EXISTS (SELECT 1 FROM pg_policies                WHERE schemaname = 'public' AND policyname = 'owners can manage enabled_practice_areas'))                                                    AS m1108_pa_rls,
  (SELECT EXISTS (SELECT 1 FROM information_schema.tables   WHERE table_schema = 'public' AND table_name = 'doc_template_library'))                                                                    AS m1109_tmpl_library,
  (SELECT EXISTS (SELECT 1 FROM information_schema.tables   WHERE table_schema = 'public' AND table_name = 'client_immigration_family_members'))                                                       AS m1110_immigration,
  (SELECT EXISTS (SELECT 1 FROM public.case_types          WHERE key = 'unlawful_presence_waiver'))                                                                                                    AS m1111_imm_case_types,
  (SELECT EXISTS (SELECT 1 FROM pg_type                   WHERE typname = 'trust_entry_type' AND typtype = 'e'))                                                                                       AS m1200_trust_acct,
  (SELECT EXISTS (SELECT 1 FROM information_schema.routines WHERE routine_schema = 'public' AND routine_name = 'migrate_retainer_balances'))                                                           AS m1201_retainer_mig,
  (SELECT EXISTS (SELECT 1 FROM information_schema.columns  WHERE table_schema = 'public' AND table_name = 'trust_reconciliations' AND column_name = 'adjusted_bank_balance'))                         AS m1202_reconcil,
  (SELECT EXISTS (SELECT 1 FROM information_schema.tables   WHERE table_schema = 'public' AND table_name = 'flat_fee_milestones'))                                                                     AS m1203_flat_fee,
  (SELECT EXISTS (SELECT 1 FROM information_schema.columns  WHERE table_schema = 'public' AND table_name = 'flat_fee_milestones' AND column_name = 'reversed_at'))                                     AS m1204_clawback,
  (SELECT EXISTS (SELECT 1 FROM information_schema.columns  WHERE table_schema = 'public' AND table_name = 'trust_ledger_entries' AND column_name = 'cleared_at'))                                     AS m1205_trust_phase2,
  (SELECT EXISTS (SELECT 1 FROM information_schema.tables   WHERE table_schema = 'public' AND table_name = 'user_mfa_recovery_codes'))                                                                 AS m1206_mfa_codes,
  (SELECT EXISTS (SELECT 1 FROM information_schema.tables   WHERE table_schema = 'public' AND table_name = 'form_editions'))                                                                           AS m1300_proof_scan,
  (SELECT EXISTS (SELECT 1 FROM public.enabled_modules     WHERE module_key = 'sig_stamp'))                                                                                                            AS m1301_sig_stamp,
  (SELECT EXISTS (SELECT 1 FROM information_schema.tables   WHERE table_schema = 'public' AND table_name = 'activity_log'))                                                                            AS m1400_activity_log,
  (SELECT EXISTS (SELECT 1 FROM information_schema.tables   WHERE table_schema = 'public' AND table_name = 'translations'))                                                                            AS m1500_translation,
  (SELECT EXISTS (SELECT 1 FROM public.enabled_modules     WHERE module_key = 'translation'))                                                                                                          AS m1501_transl_register,
  (SELECT EXISTS (SELECT 1 FROM information_schema.tables   WHERE table_schema = 'public' AND table_name = 'time_entries'))                                                                            AS m1502_time_entries,
  (SELECT EXISTS (SELECT 1 FROM information_schema.tables   WHERE table_schema = 'public' AND table_name = 'invoice_line_items'))                                                                      AS m1503_line_items,
  (SELECT EXISTS (SELECT 1 FROM information_schema.routines WHERE routine_schema = 'public' AND routine_name = 'sync_invoice_amount'))                                                                  AS m1504_invoice_guards,
  (SELECT EXISTS (SELECT 1 FROM information_schema.routines WHERE routine_schema = 'public' AND routine_name = 'process_invoice_payment'))                                                              AS m1505_payment_rpc;
